def gen_taxon_dict(nex_obj, nexson_version=None):
    """Takes a NexSON object and returns a dict of
    taxon_id -> taxon_obj
    """
    taxon_dict = {}
    for taxon in nex_obj['taxon_sets']:
        for taxon_obj in taxon['taxon_set_members']:
            taxon_dict[taxon_obj['taxon']['id']] = taxon_obj['taxon']
    return taxon_dict


